SELECT CASE WHEN r.intent IS NULL OR TRIM(r.intent) = '' THEN NULL ELSE r.intent END AS grp,


 WHERE r.created_at >= #{from} AND r.created_at < #{to}
 GROUP BY CASE WHEN r.intent IS NULL OR TRIM(r.intent) = '' THEN NULL ELSE r.intent END

SELECT CASE WHEN r.tenant_id IS NULL OR TRIM(r.tenant_id) = '' THEN NULL ELSE r.tenant_id END AS grp,


 WHERE r.created_at >= #{from} AND r.created_at < #{to}
 GROUP BY CASE WHEN r.tenant_id IS NULL OR TRIM(r.tenant_id) = '' THEN NULL ELSE r.tenant_id END
